<script>
 import {onMount} from 'svelte';
 import {getSettings,saveSettings} from '$lib/api.js';
 import {notify,uiMode,theme,user,workspaceName,compactMode} from '$lib/stores.js';
 import {locale} from '$lib/i18n.js';
 import Button from '$lib/components/Button.svelte';
 let tab='general',loading=true,saving=false;
 let settings={workspace_name:'Personal workspace',locale:'ru',timezone:'UTC',date_format:'locale',theme:'dark',mode:'simple',compact_mode:false,notifications:{system:true,deployment_errors:true,device_events:true,project_updates:true}};
 $: ru=$locale!=='en';
 const tabs=[['general','General','Общие'],['appearance','Appearance','Внешний вид'],['notifications','Notifications','Уведомления'],['account','Account','Аккаунт'],['security','Security','Безопасность'],['integrations','Integrations','Интеграции'],['about','About','О системе']];
 onMount(async()=>{const r=await getSettings();if(r.ok){settings={...settings,...r.data.settings,notifications:{...settings.notifications,...(r.data.settings?.notifications||{})}};locale.set(settings.locale);uiMode.set(settings.mode);theme.set(settings.theme||'dark');workspaceName.set(settings.workspace_name);compactMode.set(!!settings.compact_mode)}else notify(r.error||'Could not load settings','error');loading=false});
 async function save(){saving=true;const r=await saveSettings(settings);saving=false;if(r.ok){locale.set(settings.locale);uiMode.set(settings.mode);theme.set(settings.theme||'dark');workspaceName.set(settings.workspace_name);compactMode.set(!!settings.compact_mode);notify(ru?'Настройки сохранены':'Settings saved','success')}else notify(r.error||'Could not save settings','error')}
</script>
<svelte:head><title>{ru?'Настройки':'Settings'} · Yevqo</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">WORKSPACE / PREFERENCES</div><h1 class="page-title">{ru?'Настройки':'Settings'}</h1><p class="page-desc">{ru?'Настрой панель, уведомления и параметры аккаунта.':'Configure your workspace, notifications and account preferences.'}</p></div><Button variant="primary" loading={saving} disabled={loading} on:click={save}>{ru?'Сохранить изменения':'Save changes'}</Button></div>
{#if loading}<div class="empty">{ru?'Загружаем настройки…':'Loading settings…'}</div>{:else}
<div class="settings-layout">
 <nav class="settings-nav" aria-label="Settings sections">{#each tabs as item}<button class:active={tab===item[0]} on:click={()=>tab=item[0]}><span>{item[1]}</span><small>{ru?item[2]:item[1]}</small></button>{/each}</nav>
 <div class="settings-content">
  {#if tab==='general'}
   <section class="settings-panel"><h2>{ru?'Рабочая область':'Workspace'}</h2><p>{ru?'Название и региональные параметры панели.':'Workspace name and regional preferences.'}</p><label>{ru?'Название рабочей области':'Workspace name'}<input class="input" bind:value={settings.workspace_name} maxlength="80"/></label><div class="two-cols"><label>{ru?'Часовой пояс':'Timezone'}<select class="input" bind:value={settings.timezone}><option value="UTC">UTC</option><option value="Europe/Amsterdam">Europe/Amsterdam</option><option value="Europe/Berlin">Europe/Berlin</option><option value="Europe/London">Europe/London</option><option value="Europe/Moscow">Europe/Moscow</option><option value="America/New_York">America/New_York</option><option value="Asia/Tokyo">Asia/Tokyo</option></select></label><label>{ru?'Формат даты':'Date format'}<select class="input" bind:value={settings.date_format}><option value="locale">{ru?'Локальный':'Locale default'}</option><option value="iso">ISO 8601</option></select></label></div></section>
   <section class="settings-panel"><h2>{ru?'Язык':'Language'}</h2><p>{ru?'Выбери язык интерфейса.':'Choose the interface language.'}</p><select class="input narrow" bind:value={settings.locale}><option value="ru">Русский</option><option value="en">English</option></select></section>
  {:else if tab==='appearance'}
   <section class="settings-panel"><h2>{ru?'Внешний вид':'Appearance'}</h2><p>{ru?'Тема и плотность интерфейса.':'Theme and interface density.'}</p><div class="choice-grid">{#each [{id:'dark',name:ru?'Тёмная':'Dark'},{id:'light',name:ru?'Светлая':'Light'},{id:'system',name:ru?'Системная':'System'}] as choice}<button class:chosen={settings.theme===choice.id} on:click={()=>settings.theme=choice.id}><span class={'theme-swatch '+choice.id}></span><strong>{choice.name}</strong></button>{/each}</div><div class="setting-line"><div><strong>{ru?'Компактный режим':'Compact mode'}</strong><small>{ru?'Уменьшить отступы в таблицах и списках':'Reduce spacing in tables and lists'}</small></div><input type="checkbox" bind:checked={settings.compact_mode}/></div><div class="setting-line"><div><strong>Advanced Mode</strong><small>{ru?'Показывать расширенные параметры и диагностику':'Show advanced configuration and diagnostics'}</small></div><input type="checkbox" checked={settings.mode==='advanced'} on:change={(e)=>settings.mode=e.currentTarget.checked?'advanced':'simple'}/></div></section>
  {:else if tab==='notifications'}
   <section class="settings-panel"><h2>{ru?'Каналы уведомлений':'Notification preferences'}</h2><p>{ru?'Сохраняются в настройках аккаунта. События, которые ещё не поддерживают фильтрацию по категории, могут продолжать появляться.':'Preferences are saved to your account. Events whose delivery path does not yet support category filtering may still appear.'}</p>{#each [{key:'system',title:ru?'Системные события':'System notifications',desc:ru?'Состояние Control Plane и общие события':'Control Plane health and general events'},{key:'deployment_errors',title:ru?'Ошибки развёртывания':'Deployment errors',desc:ru?'Ошибки сборки и запуска приложений':'Build and application launch failures'},{key:'device_events',title:ru?'События устройств':'Device events',desc:ru?'Подключение, отключение и метрики Agent':'Agent connection, disconnection and metrics'},{key:'project_updates',title:ru?'Обновления проектов':'Project updates',desc:ru?'Изменения проектов и ресурсов':'Project and resource changes'}] as item}<div class="setting-line"><div><strong>{item.title}</strong><small>{item.desc}</small></div><input type="checkbox" bind:checked={settings.notifications[item.key]}/></div>{/each}</section>
  {:else if tab==='account'}
   <section class="settings-panel"><h2>{ru?'Информация аккаунта':'Account information'}</h2><p>{ru?'Основные данные текущего аккаунта.':'Details for the signed-in account.'}</p><div class="account-card"><span class="account-avatar">{($user?.username||'U').slice(0,1).toUpperCase()}</span><div><strong>{$user?.username||'—'}</strong><small>{$user?.email||'—'}</small></div></div><div class="readonly-row"><span>{ru?'Имя пользователя':'Username'}</span><strong>{$user?.username||'—'}</strong></div><div class="readonly-row"><span>Email</span><strong>{$user?.email||'—'}</strong></div><a class="text-link" href="/profile">{ru?'Открыть управление профилем и паролем':'Manage profile and password'} →</a></section>
  {:else if tab==='security'}
   <section class="settings-panel"><h2>{ru?'Безопасность аккаунта':'Account security'}</h2><p>{ru?'Управление паролем и дополнительной защитой.':'Password and additional account protection.'}</p><div class="security-row"><div><strong>{ru?'Пароль':'Password'}</strong><small>{ru?'Изменение пароля доступно в профиле':'Password changes are available in your profile'}</small></div><a class="outline" href="/profile">{ru?'Изменить пароль':'Change password'}</a></div><div class="security-row"><div><strong>Two-factor authentication</strong><small>{ru?'В текущем backend 2FA не реализована':'2FA is not implemented in the current backend'}</small></div><span class="coming">{ru?'Скоро':'Coming soon'}</span></div><div class="security-row"><div><strong>{ru?'Активные сессии':'Active sessions'}</strong><small>{ru?'Управление отдельными сессиями пока недоступно':'Per-session management is not available yet'}</small></div><span class="coming">{ru?'Скоро':'Coming soon'}</span></div></section>
  {:else if tab==='integrations'}
   <section class="settings-panel"><h2>{ru?'Интеграции':'Integrations'}</h2><p>{ru?'Подключение GitHub App и внешних сервисов.':'Connect GitHub App and external services.'}</p><a class="integration-link" href="/settings/integrations/github"><span class="github-mark">GH</span><span><strong>GitHub App</strong><small>{ru?'Официальная установка и выбор репозиториев':'Official installation and repository access'}</small></span><b>→</b></a></section>
  {:else}
   <section class="settings-panel"><h2>Yevqo</h2><p>{ru?'Платформа управления личной серверной инфраструктурой.':'Personal infrastructure management platform.'}</p><div class="readonly-row"><span>{ru?'Версия приложения':'Application version'}</span><strong>—</strong></div><div class="readonly-row"><span>{ru?'Control Plane':'Control Plane version'}</span><strong>—</strong></div><div class="readonly-row"><span>{ru?'Платформа':'Platform'}</span><strong>Go · SvelteKit · MySQL/MariaDB</strong></div><a class="text-link" href="https://github.com/NexLab-ceo/Yevqo" target="_blank" rel="noreferrer">{ru?'Репозиторий и документация':'Repository and documentation'} ↗</a></section>
  {/if}
 </div>
</div>
{/if}
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:var(--accent);font-weight:700;margin-bottom:7px}.settings-layout{display:grid;grid-template-columns:190px minmax(0,1fr);gap:14px;align-items:start}.settings-nav{display:grid;gap:3px;padding:6px;border:1px solid var(--border);border-radius:9px;background:var(--bg-card)}.settings-nav button{display:grid;gap:2px;padding:9px 10px;text-align:left;border:1px solid transparent;border-radius:6px;background:transparent;color:var(--text-main)}.settings-nav button.active{background:var(--bg-elevated);border-color:var(--border)}.settings-nav span{font-size:10px;font-weight:600}.settings-nav small{font-size:9px;color:var(--text-muted)}.settings-content{min-width:0}.settings-panel{padding:17px;border:1px solid var(--border);border-radius:9px;background:var(--bg-card);margin-bottom:10px}.settings-panel h2{font-size:13px;margin-bottom:5px}.settings-panel>p{font-size:10px;color:var(--text-muted);line-height:1.6;margin-bottom:15px}.settings-panel label{display:grid;gap:6px;margin:12px 0;font-size:10px;color:var(--text-muted)}.settings-panel .input{width:100%;max-width:460px}.settings-panel .narrow{max-width:240px}.two-cols{display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:720px}.choice-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.choice-grid button{display:flex;align-items:center;gap:9px;padding:12px;border:1px solid var(--border);border-radius:8px;background:var(--bg-elevated);color:var(--text-main);font-size:10px}.choice-grid button.chosen{border-color:var(--accent);background:#A5EC790D}.theme-swatch{width:28px;height:24px;border:1px solid var(--border);border-radius:5px}.theme-swatch.dark{background:#080A09}.theme-swatch.light{background:#f3f5f2}.theme-swatch.system{background:linear-gradient(90deg,#080A09 50%,#f3f5f2 50%)}.setting-line,.security-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 0;border-top:1px solid var(--border)}.setting-line>div,.security-row>div{display:grid;gap:3px}.setting-line strong,.security-row strong{font-size:10px}.setting-line small,.security-row small{font-size:9px;color:var(--text-muted)}.setting-line input{accent-color:var(--accent);width:15px;height:15px}.account-card{display:flex;align-items:center;gap:11px;padding:12px;border:1px solid var(--border);border-radius:8px;margin-bottom:12px}.account-avatar{width:34px;height:34px;display:grid;place-items:center;border-radius:8px;background:var(--bg-elevated);color:var(--accent);font-weight:700}.account-card>div{display:grid;gap:3px}.account-card strong{font-size:11px}.account-card small{font-size:9px;color:var(--text-muted)}.readonly-row{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-top:1px solid var(--border);font-size:10px}.readonly-row span{color:var(--text-muted)}.readonly-row strong{overflow-wrap:anywhere;text-align:right}.text-link{display:inline-block;margin-top:14px;color:var(--accent);font-size:10px}.outline{padding:7px 10px;border:1px solid var(--border);border-radius:7px;color:var(--text-main);font-size:9px}.coming{color:var(--text-muted);font-size:9px}.integration-link{display:flex;align-items:center;gap:11px;padding:12px;border:1px solid var(--border);border-radius:8px}.github-mark{width:32px;height:32px;display:grid;place-items:center;border-radius:7px;background:var(--bg-elevated);font-size:10px;font-weight:800}.integration-link>span:nth-child(2){display:grid;gap:3px;flex:1}.integration-link strong{font-size:11px}.integration-link small{font-size:9px;color:var(--text-muted)}.integration-link b{color:var(--accent)}
@media(max-width:760px){.settings-layout{grid-template-columns:1fr}.settings-nav{display:flex;overflow-x:auto}.settings-nav button{min-width:105px}.two-cols{grid-template-columns:1fr}.choice-grid{grid-template-columns:1fr}}
</style>